<?php
declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../config/paystack.php';$db=db();$token=preg_replace('/[^a-f0-9]/','',strtolower((string)($_GET['token']??'')));$s=$db->prepare('SELECT i.*,l.name client_name,l.email FROM invoices i JOIN leads l ON l.id=i.lead_id WHERE i.public_token=? LIMIT 1');$s->execute([$token]);$i=$s->fetch();if(!$i){http_response_code(404);exit('Invoice not found.');}if((float)$i['balance_due']<=0){header('Location: invoice-view.php?token='.$token);exit;}$reference='DWS-'.date('YmdHis').'-'.bin2hex(random_bytes(4));$amount=(int)round((float)$i['balance_due']*100);$db->prepare("INSERT INTO invoice_payments (invoice_id,lead_id,reference,gateway,amount,currency,status,metadata) VALUES (?,?,?,?,?,?, 'pending',?)")->execute([(int)$i['id'],(int)$i['lead_id'],$reference,'paystack',(float)$i['balance_due'],$i['currency'],json_encode(['invoice_token'=>$token])]);$r=paystack_request('POST','transaction/initialize',['email'=>$i['email'],'amount'=>$amount,'currency'=>$i['currency'],'reference'=>$reference,'callback_url'=>(defined('APP_URL')?rtrim(APP_URL,'/'): '').'/admin/paystack-callback.php?reference='.urlencode($reference)]);if(!$r['ok']){http_response_code(500);exit('Unable to initialize payment: '.htmlspecialchars((string)$r['error']));}$url=$r['data']['data']['authorization_url']??'';if(!$url){http_response_code(500);exit('Payment gateway returned no checkout URL.');}header('Location: '.$url);exit;
